import React, { useRef } from 'react';
import { Toast } from 'primereact/toast';
import { Menu } from 'primereact/menu';

export default function Command() {
    const toast = useRef(null);
    let items = [
        {
            label: 'New',
            icon: 'pi pi-plus',
            command: () => {
                toast.current.show({ className: 'success', summary: 'Success', detail: 'File created', life: 3000 });
            }
        },
        {
            label: 'Search',
            icon: 'pi pi-search',
            command: () => {
                toast.current.show({ className: 'warn', summary: 'Search Completed', detail: 'No results found', life: 3000 });
            }
        }
    ];

    return (
        <>
            <Toast ref={toast} />
            <Menu model={items} />
        </>
    )
}